function erpClientResetSetup(box){
  if(!box||S.user?.role!=="admin"||box.querySelector('#erp-client-reset'))return;
  const panel=document.createElement('details');panel.className='erp-step';panel.id='erp-client-reset';
  panel.innerHTML=`<summary><b>Начать CRM с чистого листа</b></summary><p class="small">CRM сохранит полную базу в двух проверенных копиях, затем уберёт из рабочей CRM карточки, занятия, оплаты, переписки и старые файлы переноса. Правила, тарифы, филиалы, группы, расписание, команда, настройки, общие задачи и расходы останутся</p><div class="row" style="gap:8px;flex-wrap:wrap"><button type="button" class="btn" data-ecr-plan>Проверить архив и очистку</button><button type="button" class="btn" data-ecr-status-check>Проверить результат</button></div><div data-ecr-result></div><p class="small" role="status" data-ecr-status></p>`;
  box.append(panel);
  const result=panel.querySelector('[data-ecr-result]'),status=panel.querySelector('[data-ecr-status]'),planButton=panel.querySelector('[data-ecr-plan]'),statusButton=panel.querySelector('[data-ecr-status-check]');let checked=null,busy=false;
  const setBusy=value=>{busy=value;panel.querySelectorAll('button,input').forEach(x=>x.disabled=value)};
  const rows=d=>Object.entries(d.counts||{}).filter(([,n])=>n).sort((a,b)=>b[1]-a[1]).map(([name,n])=>`<tr><td>${esc(name)}</td><td>${Number(n).toLocaleString('ru-RU')}</td></tr>`).join('');
  const stageLabel=value=>({queued:'Задача поставлена в очередь',local_archive:'Создаётся и проверяется архив на сервере',external_archive:'Архив шифруется и загружается во внешнее хранилище',cleaning:'Очищается рабочая CRM',completed:'Готово',failed:'Операция остановлена',interrupted:'Операция прервана перезапуском сервера'})[value]||'Проверяется состояние';
  const showStatus=out=>{checked=null;const job=out.job||{},running=['queued','running'].includes(job.state),diag=out.last_start_error,diagHtml=diag?`<details><summary>Причина ошибки запуска</summary><p class="small">${esc(diag.type)}${diag.message?' · '+esc(diag.message):''} · ${esc(diag.at||'')}</p>${(diag.frames||[]).map(x=>`<div class="small">${esc(x.file)}:${esc(x.line)} · ${esc(x.function)}</div>`).join('')}</details>`:'';if(out.completed&&out.archive){result.innerHTML=`<div class="alert" style="background:var(--accent-soft,#e7f6ee);color:inherit"><b>Клиентские данные перенесены в архив. CRM очищена.</b><br><span class="small">Архив на сервере: ${esc(out.archive.local_filename)}<br>Зашифрованная внешняя копия: ${esc(out.archive.remote_filename)}<br>Контрольная сумма: ${esc(out.archive.sha256)}</span></div>`;status.textContent='Результат подтверждён сервером. Клиентских записей осталось: 0';return 'completed'}if(running){result.innerHTML=`<div class="alert"><b>${esc(stageLabel(job.stage))}</b><br><span class="small">Задача №${esc(job.id)} выполняется на сервере. Страницу можно не держать открытой</span></div>`;status.textContent='CRM сама проверит следующий этап';return 'running'}result.innerHTML=`<div class="alert"><b>Очистка не подтверждена</b><br><span class="small">Клиентских записей в рабочей CRM: ${Number(out.client_rows_remaining||0).toLocaleString('ru-RU')}${job.error?'<br>'+esc(job.error):''}</span></div>${diagHtml}`;status.textContent=out.note||'Сформируйте новый план только после проверки состояния.';return job.state||'pending'};
  const waitForJob=async()=>{for(let i=0;i<400;i++){const out=await api('GET','/api/maintenance/client-reset/status'),state=showStatus(out);if(state!=='running')return out;await new Promise(resolve=>setTimeout(resolve,3000))}throw Error('Архивирование продолжается. Нажмите «Проверить результат» позже.')};
  statusButton.onclick=async()=>{if(busy)return;setBusy(true);status.textContent='Проверяем фактическое состояние на сервере…';try{showStatus(await api('GET','/api/maintenance/client-reset/status'))}catch(e){status.textContent=e.message||'Не удалось проверить результат'}finally{setBusy(false)}};
  planButton.onclick=async()=>{if(busy)return;checked=null;result.innerHTML='';setBusy(true);status.textContent='Проверяем состав данных и внешнее резервирование…';try{const d=await api('POST','/api/maintenance/client-reset/plan',{});checked=d;result.innerHTML=`<div class="alert"><b>Будет убрано записей: ${Number(d.total_rows||0).toLocaleString('ru-RU')}</b><br><span class="small">Обе резервные копии обязательны. После начала нового ввода старую базу можно вернуть только отдельным восстановлением</span></div><details><summary>Что уйдёт в архив</summary><table class="tbl"><thead><tr><th>Вид данных</th><th>Записей</th></tr></thead><tbody>${rows(d)}</tbody></table></details><p class="small"><b>Останется:</b> ${(d.preserved||[]).map(esc).join(', ')}</p><label class="field"><span>Для подтверждения введите:</span><b>${esc(d.confirmation)}</b><input data-ecr-confirm autocomplete="off"></label><label class="check"><input type="checkbox" data-ecr-check> Проверила список. Сохранить архив и очистить клиентские данные</label><button type="button" class="btn danger" data-ecr-apply disabled>Создать архив и очистить CRM</button>`;const apply=result.querySelector('[data-ecr-apply]'),confirm=result.querySelector('[data-ecr-confirm]'),check=result.querySelector('[data-ecr-check]');const update=()=>apply.disabled=busy||!check.checked||confirm.value!==d.confirmation;confirm.oninput=check.onchange=update;apply.onclick=async()=>{if(apply.disabled||!checked)return;const token=checked.token,confirmation=confirm.value;checked=null;setBusy(true);status.textContent='Запускаем архивирование на сервере…';try{const started=await api('POST','/api/maintenance/client-reset/apply',{token,confirmation});result.innerHTML=`<div class="alert"><b>Архивирование запущено</b><br><span class="small">Задача №${esc(started.job_id)}. Страницу можно не держать открытой</span></div>`;await waitForJob()}catch(e){status.textContent=(e.message||'Не удалось подтвердить результат')+'. Нажмите «Проверить результат»; новый план пока не создавайте.'}finally{setBusy(false)}};status.textContent='План готов. Рабочие данные ещё не изменены';}catch(e){status.textContent=e.message||'Не удалось проверить архив'}finally{setBusy(false)}};
}

function chatArchiveRestoreSetup(box){
  if(!box||S.user?.role!=='admin'||box.querySelector('#chat-archive-restore'))return;
  const panel=document.createElement('details');panel.className='erp-step';panel.id='chat-archive-restore';
  panel.innerHTML='<summary><b>Вернуть историю чатов из архива</b></summary><p class="small">Возвращает диалоги, сообщения, вложения, закрепления и личные настройки чатов из полного архива до очистки. Карточки, оплаты и занятия не возвращаются. Новые сообщения сохраняются, повтор не создаёт дублей</p><button type="button" class="btn" data-car-plan>Проверить на копии</button><div data-car-result></div><p class="small" role="status" data-car-status></p>';
  box.append(panel);
  const result=panel.querySelector('[data-car-result]'),status=panel.querySelector('[data-car-status]'),planButton=panel.querySelector('[data-car-plan]');let checked=null,busy=false;
  const lock=value=>{busy=value;panel.querySelectorAll('button,input').forEach(x=>x.disabled=value)};
  const n=value=>Number(value||0).toLocaleString('ru-RU');
  planButton.onclick=async()=>{if(busy)return;checked=null;result.innerHTML='';lock(true);status.textContent='Проверяем полный архив и объединяем переписку на копии базы…';try{const out=await api('POST','/api/maintenance/chat-archive-restore/plan',{}),p=out.preview||{},s=p.source_counts||{},a=p.added||{};checked=out;result.innerHTML=`<div class="alert"><b>В архиве: ${n(s.conversations)} чатов, ${n(s.messages)} сообщений</b><br><span class="small">Будет добавлено: ${n(a.conversations)} чатов и ${n(a.messages)} сообщений. Уже имеющиеся совпадения не дублируются. Карточки, оплаты и занятия: 0</span></div><label class="field"><span>Для подтверждения введите:</span><b>${esc(out.confirmation)}</b><input data-car-confirm autocomplete="off"></label><label class="check"><input type="checkbox" data-car-check> Проверила результат на копии. Вернуть историю чатов</label><button type="button" class="btn danger" data-car-apply disabled>Вернуть историю чатов</button>`;const apply=result.querySelector('[data-car-apply]'),input=result.querySelector('[data-car-confirm]'),check=result.querySelector('[data-car-check]');const update=()=>apply.disabled=busy||!check.checked||input.value!==out.confirmation;input.oninput=check.onchange=update;apply.onclick=async()=>{if(apply.disabled||!checked)return;const body={token:checked.token,confirmation:input.value};checked=null;lock(true);status.textContent='Создаём резервную копию и возвращаем переписку…';try{const done=await api('POST','/api/maintenance/chat-archive-restore/apply',body),r=done.result||{};result.innerHTML=`<div class="alert" style="background:var(--accent-soft,#e7f6ee);color:inherit"><b>История чатов восстановлена</b><br><span class="small">Добавлено: ${n(r.added?.conversations)} чатов и ${n(r.added?.messages)} сообщений.<br>Резервная копия перед восстановлением: ${esc(done.before_backup||'')}</span></div>`;status.textContent='Откройте раздел «Чаты» и проверьте несколько старых диалогов';}catch(e){status.textContent=e.message||'Не удалось восстановить переписку'}finally{lock(false)}};status.textContent='Проверка на копии завершена. Рабочая CRM ещё не изменена';}catch(e){status.textContent=e.message||'Не удалось проверить архив'}finally{lock(false)}};
}

function erpMamedovBalanceSetup(box,previous) {
  if(!box||S.user?.role!=='admin')return;
  const panel=document.createElement('details');panel.className='erp-step';panel.id='erp-mamedov-balance';
  panel.innerHTML='<summary><b>Исправить баланс Мамедова</b></summary><p class="small">Только карточка ERP 88202. Сначала проверяем исправление на полной копии базы. Применение выполняется отдельной кнопкой</p><div class="row" style="gap:8px;flex-wrap:wrap"><button type="button" class="btn" data-emb-plan>Проверить исправление на копии</button><button type="button" class="linkish" data-emb-open disabled>Открыть карточку</button></div><div data-emb-run></div><div data-emb-result></div><p class="small" data-emb-status role="status" aria-live="polite"></p>';
  if(previous)previous.after(panel);else box.append(panel);
  const result=panel.querySelector('[data-emb-result]'),history=panel.querySelector('[data-emb-run]'),status=panel.querySelector('[data-emb-status]'),load=panel.querySelector('[data-emb-plan]');
  const text=value=>esc(String(value??'')),money=value=>value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))?rub(Number(value)):'не подтверждено';
  let checked=null,lastRun=null,busy=false,generation=0,requestId='',studentId=null;
  const active=version=>panel.isConnected&&version===generation;
  const issues=rows=>Array.isArray(rows)&&rows.length?`<ul class="small">${rows.map(row=>`<li>${text(typeof row==='string'?row:row.reason||row.message||'Нужна сверка')}</li>`).join('')}</ul>`:'';
  const comparison=(before,after)=>{
    const fields=[['Занятий в декабре',s=>s?.invoice?.lessons,false],['Стоимость декабря',s=>s?.invoice?.price,true],['Зачтено в декабрь',s=>s?.invoice?.covered,true],['К оплате за декабрь',s=>s?.invoice?.payable,true],['Свободный баланс',s=>s?.balance?.free_deposit??s?.balance?.deposit,true],['Оплат в истории',s=>s?.payments_count,false],['Покупок в истории',s=>s?.purchases_count,false]];
    return `<div style="overflow:auto"><table class="tbl" data-emb-comparison><thead><tr><th>Показатель</th><th>До</th><th>После</th></tr></thead><tbody>${fields.map(([label,get,financial])=>`<tr><td>${label}</td><td>${financial?money(get(before)):text(get(before)??'не подтверждено')}</td><td>${financial?money(get(after)):text(get(after)??'не подтверждено')}</td></tr>`).join('')}</tbody></table></div>`;
  };
  const update=()=>{
    panel.querySelector('[data-emb-open]').disabled=busy||!studentId;
    const apply=result.querySelector('[data-emb-apply]');if(apply)apply.disabled=busy||!checked||!result.querySelector('[data-emb-confirm]')?.checked;
    const rollback=history.querySelector('[data-emb-rollback]');if(rollback)rollback.disabled=busy||lastRun?.state!=='applied'||lastRun?.can_rollback!==true||!lastRun?.rollback_token||!history.querySelector('[data-emb-rollback-confirm]')?.checked;
  };
  const setBusy=value=>{busy=value;panel.querySelectorAll('button,input').forEach(el=>el.disabled=value);if(!value)update();};
  const showRun=run=>{
    lastRun=run||null;history.innerHTML='';if(!run)return;
    const applied=run.state==='applied',canRollback=applied&&run.can_rollback===true&&typeof run.rollback_token==='string'&&!!run.rollback_token,hasBackup=run.backup_created===true||typeof run.backup_filename==='string'&&!!run.backup_filename;
    const link=run.payment_link,linkUrl=link?.url;let publicUrl='';try{if(applied&&!run.state_changed_since_apply&&linkUrl&&['http:','https:'].includes(new URL(linkUrl,location.href).protocol))publicUrl=new URL(linkUrl,location.href).href}catch(_){}
    history.innerHTML=`<section class="panel"><h4>${run.state==='rolled_back'?'Исправление отменено':applied?'Исправление применено':'Состояние исправления требует проверки'}</h4><p class="small">Операция №${text(run.run_id)}${run.created_at?' · '+text(run.created_at):''}${hasBackup?' · резервная копия создана':''}</p>${hasBackup&&run.backup_filename?`<details><summary>Резервная копия</summary><p class="small">${text(run.backup_filename)}</p></details>`:''}${run.before_summary&&run.after_summary?`<details data-emb-saved-result><summary>Сохранённые итоги операции</summary>${comparison(run.before_summary,run.after_summary)}</details>`:''}${run.summary_note?`<p class="small" data-emb-summary-note>${text(run.summary_note)}</p>`:''}<section data-emb-current><h4>Текущее состояние карточки</h4>${run.current_summary?`<div class="finance-numbers"><div><small>Зачтено в декабрь</small><b data-emb-current-paid>${money(run.current_summary.invoice?.covered)}</b></div><div><small>К оплате за декабрь</small><b data-emb-current-due>${money(run.current_summary.invoice?.payable)}</b></div><div><small>Свободный баланс</small><b data-emb-current-balance>${money(run.current_summary.balance?.free_deposit??run.current_summary.balance?.deposit)}</b></div></div><p class="small">Оплат в истории: ${text(run.current_summary.payments_count??'не подтверждено')} · покупок: ${text(run.current_summary.purchases_count??'не подтверждено')}</p>`:'<p class="small">Текущее состояние не подтверждено. Перечитайте данные</p>'}</section>${publicUrl?`<p><a class="linkish" data-emb-public href="${text(publicUrl)}" target="_blank" rel="noopener noreferrer">Открыть страницу оплаты${Number.isInteger(link.amount)?' · '+money(link.amount):''}</a></p>`:''}${canRollback?'<details><summary>Отменить только это исправление</summary><p class="small">Перед отменой CRM проверит, что записи после этой операции не изменились</p><label class="check"><input type="checkbox" data-emb-rollback-confirm> Вернуть состояние до этой операции</label><button type="button" class="btn" data-emb-rollback disabled>Отменить это исправление</button></details>':applied?'<p class="small">Отмена сейчас недоступна. Перечитайте состояние: записи могли измениться после исправления</p>':''}</section>`;
    history.querySelector('[data-emb-rollback-confirm]')?.addEventListener('change',update);
    const rollback=history.querySelector('[data-emb-rollback]');if(rollback)rollback.onclick=rollbackRun;
  };
  const showPlan=plan=>{
    checked=null;
    const ready=plan.erp_id==='88202'&&plan.can_apply===true&&plan.plan_ready===true&&plan.production_apply_available===true&&plan.preview_on_copy===true&&typeof plan.token==='string'&&!!plan.token&&plan.before&&plan.without_balance;
    result.innerHTML=`<h4>${plan.already_applied===true?'Баланс уже исправлен':ready?'Исправление проверено на копии':'Исправление пока недоступно'}</h4>${plan.already_applied!==true&&(plan.before||plan.without_balance)?comparison(plan.before,plan.without_balance):''}<p class="small">Ноябрьское покрытие 8 100 ₽ сохраняется по текущему учёту CRM. Точные счета ERP не установлены. Новая оплата не создаётся</p>${issues(plan.issues||plan.blockers)}${ready?'<label class="check"><input type="checkbox" data-emb-confirm> Проверила суммы и сохранность истории; применить это исправление</label><button type="button" class="btn primary" data-emb-apply disabled>Применить проверенное исправление</button>':'<p class="small">Рабочие записи этим просмотром не изменены. Для новой проверки перечитайте данные</p>'}`;
    if(ready){checked={token:plan.token};requestId=window.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);result.querySelector('[data-emb-confirm]').onchange=update;result.querySelector('[data-emb-apply]').onclick=apply;}
  };
  const runFrom=reply=>reply.last_run?{...reply,...reply.last_run}:reply.run_id?reply:null;
  const apply=async()=>{
    if(busy||!checked||!result.querySelector('[data-emb-confirm]')?.checked)return;
    const version=++generation,token=checked.token;setBusy(true);status.textContent='Создаём резервную копию и применяем проверенное исправление…';
    try{
      const reply=await api('POST','/api/erp/balance-recovery/apply',{erp_id:'88202',token,request_id:requestId});if(!active(version))return;
      checked=null;result.innerHTML='';const run=runFrom(reply);if(!run||run.state!=='applied')throw Error('Сервер не подтвердил применение. Перечитайте состояние');showRun(run);status.textContent='Исправление применено. Проверьте карточку клиента';
    }catch(error){if(active(version)){checked=null;result.innerHTML='';status.textContent=(error.message||'Результат применения не подтверждён')+'. Нажмите «Проверить исправление на копии», чтобы перечитать состояние.'}}finally{if(active(version))setBusy(false)}
  };
  const rollbackRun=async()=>{
    if(busy||lastRun?.can_rollback!==true||!lastRun.rollback_token||!history.querySelector('[data-emb-rollback-confirm]')?.checked)return;
    const version=++generation,run=lastRun;setBusy(true);status.textContent='Проверяем возможность отмены этой операции…';
    try{const reply=await api('POST',`/api/erp/balance-recovery/${encodeURIComponent(run.run_id)}/rollback`,{token:run.rollback_token});if(!active(version))return;checked=null;result.innerHTML='';const restored=runFrom(reply);if(!restored||restored.state!=='rolled_back')throw Error('Сервер не подтвердил отмену');showRun(restored);status.textContent='Это исправление отменено. Исходное состояние восстановлено'}
    catch(error){if(active(version)){if(lastRun)lastRun={...lastRun,can_rollback:false,rollback_token:null,current_summary:null,state_changed_since_apply:true,summary_note:'Не удалось подтвердить текущее состояние. Перечитайте данные.'};showRun(lastRun);status.textContent=(error.message||'Результат отмены не подтверждён')+'. Перечитайте состояние перед дальнейшими действиями.'}}finally{if(active(version))setBusy(false)}
  };
  load.onclick=async()=>{
    if(busy)return;const version=++generation;checked=null;studentId=null;showRun(null);result.innerHTML='';setBusy(true);status.textContent='Читаем рабочее состояние и проверяем исправление на полной копии…';
    try{
      const context=await api('GET','/api/erp/balance-recovery/context?erp_id=88202');if(!active(version))return;
      if(context.erp_id==='88202'&&Number.isInteger(context.student_id||context.student?.id)&&(context.student_id||context.student.id)>0)studentId=context.student_id||context.student.id;showRun(context.last_run||null);
      const plan=await api('POST','/api/erp/balance-recovery/plan',{erp_id:'88202'});if(!active(version))return;if(Object.prototype.hasOwnProperty.call(plan,'last_run'))showRun(plan.last_run);if(plan.erp_id==='88202'&&Number.isInteger(plan.student_id)&&plan.student_id>0)studentId=plan.student_id;showPlan(plan);status.textContent='Проверка завершена. Рабочие записи не изменены';
    }catch(error){if(active(version)){checked=null;if(lastRun)showRun({...lastRun,can_rollback:false,rollback_token:null,current_summary:null});result.innerHTML='';status.textContent=error.message||'Не удалось проверить исправление'}}finally{if(active(version))setBusy(false)}
  };
  panel.querySelector('[data-emb-open]').onclick=()=>{if(studentId&&typeof openStudent==='function')openStudent(studentId,{tab:'abon'});};
}


function erpFinancialAuditSetup(box,previous) {
  if(!box||S.user?.role!=="admin")return;
  const panel=document.createElement('details');panel.className='erp-step';panel.id='erp-financial-audit';
  panel.innerHTML=`<summary><b>Сверка исторических оплат</b></summary><p class="small">Только чтение: источники оплат, повторные записи и зачёты между периодами. Эта проверка не создаёт оплаты, возвраты или изменения карточки</p><div class="row" style="gap:8px;align-items:end;flex-wrap:wrap"><div class="field"><label for="efa-erp">ID клиента ERP</label><input id="efa-erp" value="117559" autocomplete="off"></div><div class="field"><label for="efa-month">Проверяемый месяц</label><input id="efa-month" type="month" value="2026-12"></div><button type="button" class="btn" data-efa-read>Сверить источники</button></div><div data-efa-report></div><p class="small" role="status" aria-live="polite" data-efa-status></p>`;
  if(previous)previous.after(panel);else box.append(panel);
  const output=panel.querySelector('[data-efa-report]'),status=panel.querySelector('[data-efa-status]'),erp=panel.querySelector('#efa-erp'),month=panel.querySelector('#efa-month'),button=panel.querySelector('[data-efa-read]');
  const text=value=>esc(String(value??'')),amount=value=>value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))?rub(Number(value)):'не подтверждено';
  const actionText=value=>value.action==='exclude_proved_technical_duplicate'?'Исключить доказанный технический дубль оплаты CRM №'+value.payment_id:value.action==='bind_source_payment'?'Связать оплату CRM №'+value.payment_id+' с покупкой №'+value.subscription_id+' на '+amount(value.amount)+' · счёт ERP '+value.source_invoice_id+' · операция ERP '+value.source_operation_id:value.action==='verify_one_time_carry'?'Проверить однократный перенос из мероприятия':value.action==='preserve_owner_confirmed_carry'?'Сохранить один существующий перенос «'+String(value.label||'На следующий турнир')+'» на '+amount(value.amount):['use_owner_confirmed_erp_balance_snapshot','use_confirmed_erp_balance_snapshot'].includes(value.action)?'Использовать подтверждённый снимок ERP: '+amount(value.amount)+' на '+value.as_of_date:value.action==='exclude_old_history_from_free_and_future_funding'?'Не использовать неполную историю до '+value.cutoff_date+' для свободного остатка и будущих покупок':value.action==='preserve_sold_purchases_and_attendance'?'Сохранить проведённые покупки и отметки посещений':'Нужна сверка источника';
  const reason=value=>typeof value==='string'?value:value?.reason||value?.note||value?.message||(value?.action?actionText(value):value?.evidence_id||(value?.field?value.field+': '+String(value.value??''):'Нужна сверка источника'));
  const notes=values=>values?.length?`<ul class="small">${values.map(value=>`<li>${text(reason(value))}</li>`).join('')}</ul>`:'';
  const moneySummary=(data,unverified=false)=>{
    if(!data)return '<p class="small">Нужна сверка. Подтверждённый итог не рассчитан</p>';
    const balance=data.balance||{},allocation=data.allocation||{};
    return `<div class="finance-numbers"><div><small>${unverified?'Учтено в CRM, включая технические записи':'Учтено поступлений с возвратами'}</small><b>${amount(balance.paid_total)}</b></div><div><small>${unverified?'Долг CRM — требует сверки':'Долг'}</small><b>${amount(balance.debt)}</b></div><div><small>Будущие покупки</small><b>${amount(balance.upcoming)}</b></div><div><small>${unverified?'Остаток CRM — требует сверки':'Доступный остаток'}</small><b>${amount(balance.deposit)}</b></div>${balance.restricted_deposit!==undefined?`<div><small>Остаток с ограничением источника</small><b>${amount(balance.restricted_deposit)}</b></div>`:''}</div><details><summary>Все покупки и зачтённые суммы</summary><div style="overflow:auto"><table class="tbl"><thead><tr><th>Покупка CRM</th><th>Период</th><th>Стоимость</th><th>Зачтено</th><th>Из оплат CRM</th></tr></thead><tbody>${(allocation.obligations||[]).map(s=>`<tr><td>№${text(s.id)}</td><td>${text(s.month)}</td><td>${amount(s.price)}</td><td>${amount((allocation.covered||{})[s.id])}</td><td>${((allocation.sources||{})[s.id]||[]).map(p=>`№${text(p.payment_id)}: ${amount(p.amount)}`).join('<br>')||'нет зачётов'}</td></tr>`).join('')}</tbody></table></div><p class="small">Остатки оплат: ${Object.entries(allocation.payment_remaining||{}).map(([id,sum])=>`№${text(id)} — ${amount(sum)}`).join('; ')||'нет данных'}</p></details>`;
  };
  const eventText=value=>{
    if(typeof value==='string')return text(value);
    const kind={reported_free_balance:'Ожидаемый свободный остаток',reported_invoice:'Покупка из обращения',reported_fifo_split:'Распределение из обращения',reported_event_carry:'Перенос из мероприятия'}[value?.kind]||'';
    return [value?.name||value?.title||value?.event_name||kind||(value?.action?actionText(value):''),value?.date||value?.event_at||value?.month||'',value?.amount!==undefined?amount(value.amount):'',...(value?.parts||[]).map(p=>String(p.source_month)+' — '+amount(p.amount)),value?.source_invoice_id?'счёт ERP '+String(value.source_invoice_id):'',value?.target_invoice_id?'целевой счёт ERP '+String(value.target_invoice_id):'',...Object.entries(value?.source_identity||{}).map(([key,id])=>({event_id:'ID мероприятия ERP',sale_id:'ID продажи ERP',invoice_id:'ID счёта ERP'}[key]||'ID источника')+': '+id),value?.evidence_id?'источник '+String(value.evidence_id):'',...(value?.evidence_ids||[]),value?.note||''].filter(Boolean).map(text).join(' · ');
  };
  const authoritativeHtml=d=>{
    const snapshot=d.erp_balance_snapshot,plan=d.authoritative_balance_plan;
    if(!snapshot)return '';
    const credit=plan?.carry_credit_plan;
    return `<section class="panel" data-efa-authoritative>
      <h4>${snapshot.confirmed===true?'Подтверждённый остаток ERP':'Снимок остатка ERP требует подтверждения'}</h4><b>${amount(snapshot.amount)}</b>
      <p class="small">На ${text(snapshot.as_of_date||'дату из источника')}${snapshot.date_precision==='day'?' · точное время снимка не указано':''}. ${snapshot.provenance==='owner_confirmation'?'Подтверждено владельцем по данным ERP.':''}</p>
      ${snapshot.history_complete===false?'<p class="small">История операций неполная. Старые записи не подтверждают свободные средства или оплату будущих покупок</p>':''}
      ${plan?`<h4>План сверки — ${plan.applied?'состояние по ответу сервера':'выключен, ещё не применён'}</h4>
        <div class="finance-numbers"><div><small>Доступный остаток в плане</small><b data-efa-planned-available>${amount(plan.available_balance??plan.free_balance)}</b></div>
        ${credit?`<div><small>${text(credit.label||'Существующий перенос')}</small><b>${amount(credit.amount)}</b></div>`:''}</div>
        <p class="small">Основа ERP на дату снимка: ${amount(plan.free_balance)}. Из неполной старой истории для будущих покупок: ${amount(plan.historical_funds_available_for_future)}</p>
        ${credit?'<p class="small">Перенос учтён отдельно и один раз. Это существующий остаток; новая оплата не создаётся. Следующий турнир можно выбрать позже</p>':''}
        <p class="small" data-efa-current-balance>Остаток на текущий момент: ${amount(plan.current_free_balance)}. Новые операции после даты снимка сверяются отдельно</p>
        <p class="small">Точная новая оплата уменьшает сумму к оплате по своей покупке. Для подтверждения общего текущего остатка нужна отдельная сверка</p>
        ${plan.requires_new_snapshot||plan.newer_operations_present?'<p class="small" data-efa-newer-warning>Есть операции после снимка ERP. Нужен новый снимок; нулевой остаток на прошлую дату не обнуляет новые поступления</p>':''}
        ${plan.requires_same_day_reconciliation?'<p class="small" data-efa-same-day-warning>Есть операции в день снимка. Его точное время неизвестно, поэтому их включение нужно сверить отдельно</p>':''}
        ${plan.protected_invoices?.length?`<div style="overflow:auto"><table class="tbl" data-efa-protected><thead><tr><th>Покупка CRM / месяц</th><th>Стоимость</th><th>Зачёт CRM до сверки</th><th>Подтверждено после даты отсечения</th><th>План подтверждённого зачёта</th><th>К оплате в плане</th></tr></thead><tbody>${plan.protected_invoices.map(r=>`<tr><td>№${text(r.subscription_id)} · ${text(r.month)}</td><td>${amount(r.price)}</td><td>${amount(r.crm_covered)}</td><td>${amount(r.confirmed_post_cutoff_covered)}</td><td>${amount(r.planned_covered)}</td><td>${amount(r.planned_payable??r.coverage_unverified)}${notes(r.coverage_blockers)}</td></tr>`).join('')}</tbody></table></div><p class="small">Использование доступного остатка не выбрано. План не оплачивает покупки автоматически</p>`:''}
        ${notes(plan.coverage_blockers)}<p class="small">Рабочий долг, покупки и отметки посещений не изменены. Значения выше относятся к отключённому плану</p>`:''}
      </section>`;
  };
  const snapshotRelation=r=>r.snapshot_inclusion==='requires_same_day_reconciliation'?'В день снимка; точное время требует сверки':r.snapshot_inclusion==='before_snapshot_date'||r.included_in_snapshot===true?'До даты снимка; повторно не прибавляется':r.snapshot_inclusion==='after_snapshot'||r.included_in_snapshot===false?'После снимка; сверяется отдельно':'Включение в снимок требует сверки';
  const cutoffHtml=data=>{
    if(!data)return '';
    const coverage=data.source_coverage||{},real=(data.operations||[]).filter(r=>r.origin!=='technical_backfill'),technical=(data.operations||[]).filter(r=>r.origin==='technical_backfill');
    const table=rows=>`<div style="overflow:auto"><table class="tbl"><thead><tr><th>Операция ERP / запись CRM</th><th>Дата</th><th>Сумма</th><th>Вид записи</th><th>Источник</th><th>Относительно снимка ERP</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${text(r.operation_id||'ID не подтверждён')} · ${r.payment_id?'CRM №'+text(r.payment_id):'в CRM не связана'}${r.cancelled?'<div class="small">Отменена</div>':''}</td><td>${text(r.paid_at)}</td><td>${amount(r.amount)}</td><td>${r.origin==='technical_backfill'?'Техническая запись, не поступление':['income','in','Credit'].includes(r.direction)?'Поступление':['refund','out','Debit'].includes(r.direction)?'Возврат':'Нужна сверка'}</td><td>${r.origin==='technical_backfill'?'Создана CRM':r.confirmation==='source_confirmed'?'Подтверждено источником':'Нужна сверка'}${notes(r.issues)}</td><td>${snapshotRelation(r)}</td></tr>`).join('')}</tbody></table></div>`;
    return `<section data-efa-cutoff><h4>Сверка операций после ${text(data.after_date||'даты отсечения')}</h4>
      <p class="small" data-efa-source-coverage>${coverage.last_retained_payment_date?'Последняя сохранённая '+(coverage.last_retained_payment?.date_is_fallback?'дата в реестре ERP':'оплата ERP')+' — '+text(coverage.last_retained_payment_date)+(coverage.last_retained_payment?.date_is_fallback?' (поле «'+text(coverage.last_retained_payment.date_origin||'дата источника')+'»)':'')+'. ':'Последняя дата оплаты ERP не подтверждена. '}Полнота источника за проверяемый период не подтверждена. Пустой список не означает, что оплат не было</p>
      <p class="small">Снимок ERP — на ${text(data.as_of_date||'дату из источника')}. Ранее учтённые операции повторно не прибавляются к остатку</p>
      <div class="finance-numbers"><div><small>Подтверждено по сохранённым данным</small><b>${amount(data.totals?.confirmed_income)}</b></div><div><small>Подтверждённые возвраты</small><b>${amount(data.totals?.confirmed_refunds)}</b></div><div><small>Оплаты для сверки</small><b>${amount(data.totals?.unverified_income)}</b></div><div><small>Возвраты для сверки</small><b>${amount(data.totals?.unverified_refunds)}</b></div></div>
      ${real.length?table(real):'<p class="small">В доступной истории нет исходных операций за этот период. Полнота истории не подтверждена</p>'}
      ${technical.length?`<details data-efa-technical><summary>Технические записи CRM: ${text(data.technical_count??technical.length)} · ${amount(data.technical_total??data.totals?.technical_total)}</summary><p class="small">Это записи восстановления учёта. Они показаны отдельно и не считаются новыми поступлениями после даты отсечения</p>${table(technical)}</details>`:''}</section>`;
  };
  const ownerCarryHtml=r=>r?`<section class="panel" data-efa-owner-carry><h4>${r.confirmed===true?'Подтверждённый перенос из мероприятия':'Перенос из мероприятия требует подтверждения'}</h4><p>${amount(r.amount)} · ${text(r.label||'На следующий турнир')}${r.once?' · один раз':''}</p><p class="small">${r.provenance==='owner_confirmation'?'Основание — подтверждение владельца. ':''}Это существующий остаток, новая оплата не создаётся. ${r.destination_pending?'Следующий турнир пока не выбран; его можно указать позже.':'Назначение сверяется отдельно.'} Исходная операция остаётся предметом отдельной сверки</p></section>`:'';
  const render=d=>{
    const candidates=d.synthetic_candidates||[],cross=d.cross_period_allocations||[],carry=d.event_carry||{},trace=d.source_trace||{};
    const proposed=d.after||d.proposed_after,partial=!!proposed&&(d.plan_complete===false||!d.after),afterTitle=partial?'После доказанных исправлений — неполный план':proposed?'После подтверждённых исправлений':'После проверки исходных связей';
    const sourceConfirmed=d.erp_balance_snapshot?.confirmed===true,incomplete=sourceConfirmed&&d.erp_balance_snapshot.history_complete===false,expectations=(d.expectations||[]).filter(e=>!(sourceConfirmed&&['reported_free_balance','previously_reported_crm_free_balance'].includes(e.kind)&&Number(e.amount)!==Number(d.erp_balance_snapshot.amount))&&!(carry.owner_requirement?.confirmed===true&&e.kind==='reported_event_carry'));
    output.innerHTML=`<h4>${text(d.student?.name||'Карточка не сопоставлена')} · ERP ${text(d.erp_id||erp.value)} · ${text(d.target_month||month.value)}</h4>${authoritativeHtml(d)}${expectations.length?`<details data-efa-expectations><summary>Ожидания из обращения — требуют подтверждения источниками</summary><ul class="small">${expectations.map(e=>`<li>${eventText(e)}${e.verified===true?' · подтверждено':' · ещё не подтверждено'}</li>`).join('')}</ul></details>`:''}<div><section data-efa-before><h4>${incomplete?'Расчёт CRM по неполной истории — требует сверки':'Сейчас'}</h4>${moneySummary(d.crm_observed||d.before,incomplete)}</section><section data-efa-after><h4>${afterTitle}</h4>${partial?'<p class="small">Расчёт охватывает только доказанные связи и технические дубли. Остальные источники и мероприятия ещё требуют сверки</p>':''}${moneySummary(proposed,incomplete)}</section></div>${cutoffHtml(d.post_cutoff)}
      <h4>Кандидаты на повторные или неподтверждённые записи</h4>${candidates.length?candidates.map(c=>`<details><summary>Оплата CRM №${text(c.payment_id)} · ${amount(c.amount)} · ${text(({candidate:'возможный дубль',source_supported_duplicate:'повтор подтверждён источником',unproven_legacy:'источник старой записи не подтверждён'})[c.classification]||'нужна сверка')}</summary><p class="small">Покупка CRM №${text(c.subscription_id||'не определена')} · связанные оплаты: ${(c.related_payment_ids||[]).map(text).join(', ')||'не определены'}<br>Операции ERP: ${(c.source_operation_ids||[]).map(text).join(', ')||'не подтверждены'}<br>Счета ERP: ${(c.source_invoice_ids||[]).map(text).join(', ')||'не подтверждены'}</p>${notes(c.evidence)}${notes(c.blockers)}</details>`).join(''):'<p class="small">В текущем ответе кандидатов нет. Полнота учёта подтверждается отдельно</p>'}
      <h4>Зачёты между периодами</h4>${cross.length?`<div style="overflow:auto"><table class="tbl" data-efa-cross-period><thead><tr><th>Покупка / месяц</th><th>Исходная оплата / месяц</th><th>Зачтено</th><th>Основание</th></tr></thead><tbody>${cross.map(c=>`<tr><td>№${text(c.subscription_id)} · ${text(c.month)}</td><td>№${text(c.payment_id)} · ${text(c.source_month)}</td><td>${amount(c.amount)}</td><td>${c.kind==='explicit'?'Явная связь источника':'Текущее распределение CRM'}<div class="small">${['confirmed','verified','source_supported','source_confirmed','proven'].includes(c.proof_status)?'Связь подтверждена':'Нужна сверка источника'}</div></td></tr>`).join('')}</tbody></table></div>`:'<p class="small">Подтверждённых строк в ответе нет</p>'}
      <h4>Мероприятия и перенос остатка</h4>${ownerCarryHtml(carry.owner_requirement)}<p class="small">${text(carry.owner_requirement?.confirmed===true?'Перенос сохранён в плане один раз; следующий турнир можно выбрать позже':({blocked:'Нужна сверка; перенос не подтверждён',not_observed:'Источник мероприятия не найден',prepared:'Проверочный план подготовлен'})[carry.state]||'Нужна сверка')}</p>${carry.expected?.length&&carry.owner_requirement?.confirmed!==true?`<details><summary>Сведения из обращения</summary><ul class="small">${carry.expected.map(e=>`<li>${eventText(e)}</li>`).join('')}</ul></details>`:''}${carry.source_candidates?.length?`<details><summary>Кандидаты из источника</summary><ul class="small">${carry.source_candidates.map(e=>`<li>${eventText(e)}</li>`).join('')}</ul></details>`:''}${carry.plans?.length?`<details><summary>Предлагаемый учёт — ещё не применён</summary><ul class="small">${carry.plans.map(e=>`<li>${eventText(e)}</li>`).join('')}</ul></details>`:''}${notes(carry.notes)}${notes(carry.blockers)}
      <details><summary>Точные связи счетов и операций ERP</summary>${(trace.invoice_resolutions||[]).map(r=>`<p class="small">Счёт ERP ${text(r.invoice_id)} → покупки CRM ${(r.subscription_ids||[]).map(text).join(', ')||'не сопоставлены'} · ${r.exact?'точная связь':'нужна сверка'}</p>`).join('')}${(trace.operation_resolutions||[]).map(r=>`<p class="small">Операция ERP ${text(r.operation_id)} → оплаты CRM ${(r.payment_ids||[]).map(text).join(', ')||'не сопоставлены'} · ${r.source_relation_confirmed===true?'реквизиты источника подтверждены':r.exact?'ID оплаты сопоставлен, нужна сверка реквизитов':'нужна сверка'}</p>`).join('')}</details>${d.proposed_changes?.length?`<h4>Предложенные изменения — без применения</h4>${notes(d.proposed_changes)}`:''}${notes([...(d.blockers||[]),...(d.issues||[])])}<p class="small">Рабочие данные не изменены. Кнопки применения в этой сверке нет</p>`;
  };
  button.onclick=async()=>{
    if(!erp.value.trim()||!/^\d{4}-\d{2}$/.test(month.value)){status.textContent='Укажите ID клиента ERP и проверяемый месяц';return;}
    button.disabled=true;erp.disabled=true;month.disabled=true;output.innerHTML='';status.textContent='Читаем источники и проверяем распределения без изменения данных…';
    try{const d=await api('GET','/api/erp/financial-audit?erp_id='+encodeURIComponent(erp.value.trim())+'&month='+encodeURIComponent(month.value));render(d);status.textContent='Сверка прочитана. Рабочие записи не изменены';}
    catch(error){status.textContent=error.message||'Не удалось прочитать сверку';}finally{button.disabled=false;erp.disabled=false;month.disabled=false;}
  };
  erp.oninput=month.oninput=()=>{output.innerHTML='';status.textContent='Сверьте источники для выбранной карточки и месяца';};
}
